css:
.cat-sidebar{display:flex;flex-direction:column;gap:2px;width:216px;padding:10px 8px;background:rgba(250,250,253,.45);border-right:1px solid var(--cat-color-stroke-softer);font-family:var(--cat-font-family-ui)}
.cat-nav-item{display:flex;align-items:center;gap:9px;height:30px;padding:0 9px;border-radius:var(--cat-size-radius-sm);font-size:var(--cat-font-size-base);color:var(--cat-color-ink-mid);cursor:pointer;user-select:none;transition:background var(--cat-motion-fast),color var(--cat-motion-fast)}
.cat-nav-item:hover{background:rgba(255,255,255,.5);color:var(--cat-color-ink-hi)}
.cat-nav-item.active{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));color:#fff;font-weight:var(--cat-font-weight-medium);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.cat-nav-item.active .ni-icon{color:#fff}
.ni-icon{width:15px;display:grid;place-items:center;opacity:.75}
.cat-nav-item.active .ni-icon{opacity:1}
.cat-chevron{margin-left:auto;transition:transform var(--cat-motion-med) var(--cat-motion-ease-out);font-size:9px;color:var(--cat-color-ink-faint)}
.cat-nav-item[aria-expanded="true"] .cat-chevron{transform:rotate(180deg)}
.cat-sub{display:none;flex-direction:column;gap:2px;padding:2px 0 2px 30px}
.cat-nav-item[aria-expanded="true"]+.cat-sub{display:flex}
.cat-sub .cat-nav-item{height:27px;font-size:var(--cat-font-size-md)}
.cat-section{padding:0 12px;margin:14px 0 4px;font:600 var(--cat-font-size-xs) var(--cat-font-family-ui);letter-spacing:.06em;text-transform:uppercase;color:var(--cat-color-ink-faint)}
